import { useState } from 'react';
import { Calendar, Button } from '@jinx-ui/react';

interface QuickOption {
  label: string;
  getDate: () => Date;
}

interface ReportDatePickerProps {
  onChange: (date: Date) => void;
  defaultValue?: Date;
}

function startOfDay(date: Date): Date {
  const result = new Date(date);
  result.setHours(0, 0, 0, 0);
  return result;
}

function addDays(date: Date, days: number): Date {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
  return result;
}

const quickOptions: QuickOption[] = [
  { label: 'Сегодня', getDate: () => startOfDay(new Date()) },
  { label: 'Вчера', getDate: () => addDays(startOfDay(new Date()), -1) },
  { label: 'Неделя назад', getDate: () => addDays(startOfDay(new Date()), -7) },
];

export default function ReportDatePicker({ onChange, defaultValue }: ReportDatePickerProps) {
  const [selectedDate, setSelectedDate] = useState<Date>(
    defaultValue ? startOfDay(defaultValue) : startOfDay(new Date())
  );

  const applyDate = (date: Date) => {
    const normalized = startOfDay(date);
    setSelectedDate(normalized);
    onChange(normalized);
  };

  return (
    <div
      className="jx-stack jx-panel"
      style={{ gap: 'var(--jx-space-md)', padding: 'var(--jx-space-md)' }}
    >
      <div
        className="jx-group"
        role="group"
        aria-label="Быстрый выбор даты"
        style={{ gap: 'var(--jx-space-sm)' }}
      >
        {quickOptions.map((option) => {
          const optionDate = option.getDate();
          const isActive = optionDate.getTime() === selectedDate.getTime();
          return (
            <Button
              key={option.label}
              type="button"
              variant={isActive ? 'primary' : 'secondary'}
              size="sm"
              aria-pressed={isActive}
              onClick={() => applyDate(optionDate)}
            >
              {option.label}
            </Button>
          );
        })}
      </div>
      <Calendar
        mode="single"
        value={selectedDate}
        onChange={(date: Date) => applyDate(date)}
        className="jx-calendar"
        aria-label="Календарь выбора даты отчёта"
      />
    </div>
  );
}

